const $=s=>document.querySelector(s);let world,run,mode='endless',level=1,character='krishna',screen='menu',last=0,toastTimer,finished=false,powerStamp="";
const store={get(k,d){try{return JSON.parse(localStorage.getItem('vd-'+k))??d}catch{return d}},set(k,v){try{localStorage.setItem('vd-'+k,JSON.stringify(v))}catch{}}};
const settings={sound:true,music:true,musicVolume:.45,sfxVolume:.75,quality:'auto',vibration:true,...store.get('settings',{})};const audio=new GameAudio(settings);let progress=cleanProgress(store.get('progress',{})),footTimer=0;document.addEventListener('pointerdown',()=>audio.unlock(),{once:true});character=store.get('character','krishna');if(!CHARACTERS.some(c=>c.id===character))character='krishna';let best=store.get('best',0),unlocked=store.get('unlocked',1);let storage;try{storage=localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Storage unavailable')}};}const economy=new Economy(storage);let bank=economy.state.coins,runId='',settlement=null;if(!economy.state.owned.includes(character))character='krishna';
function sound(){audio.effect('ui');}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function stats(){bank=economy.state.coins;$('#best').textContent=Math.floor(best)+' m';$('#bank').textContent=bank.toLocaleString();}
let previewCharacter=character;
function updateCharacterPreview(){const c=CHARACTERS.find(c=>c.id===previewCharacter);world.character(c.id);$('#character-name').textContent=c.name;$('#character-detail').textContent=c.detail+(economy.state.owned.includes(c.id)?' · Owned':` · ${c.price} coins`);document.querySelectorAll('[data-char]').forEach(b=>b.classList.toggle('selected',b.dataset.char===c.id));const owned=economy.state.owned.includes(c.id);$('#character-select').textContent=owned?(c.id===character?'Selected':'Select'):`Unlock · ${c.price} coins`;$('#character-select').disabled=!owned&&economy.state.coins<c.price;}
function closeCharacters(){world.menuLayout='home';world.character(character);$('#character-screen').hidden=true;$('#menu').hidden=false;screen='menu';}
$('#characters-open').onclick=()=>{audio.effect('ui');screen='characters';previewCharacter=character;world.menuLayout='characters';$('#menu').hidden=true;$('#character-screen').hidden=false;$('#character-roster').innerHTML=CHARACTERS.map(c=>`<button data-char="${c.id}" aria-label="${c.name}" style="--outfit:${c.color}"><img class="roster-portrait" data-portrait="${c.id}" alt=""><small>${economy.state.owned.includes(c.id)?'': '🔒 '}${c.short}</small></button>`).join('');document.querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>{previewCharacter=b.dataset.char;updateCharacterPreview();audio.effect('ui');});updateCharacterPreview();let portraitIndex=0;function loadPortrait(){if(screen!=='characters'||portraitIndex>=CHARACTERS.length)return;const id=CHARACTERS[portraitIndex++].id,el=document.querySelector('[data-portrait="'+id+'"]');if(el)el.src=world.portrait(id);requestAnimationFrame(loadPortrait);}requestAnimationFrame(loadPortrait);};
$('#character-back').onclick=closeCharacters;
function cycleCharacter(d){const i=CHARACTERS.findIndex(c=>c.id===previewCharacter);previewCharacter=CHARACTERS[(i+d+CHARACTERS.length)%CHARACTERS.length].id;updateCharacterPreview();audio.effect('ui');}
$('#character-prev').onclick=()=>cycleCharacter(-1);$('#character-next').onclick=()=>cycleCharacter(1);
$('#character-select').onclick=()=>{if(!economy.state.owned.includes(previewCharacter)){const purchase=economy.buyCharacter(previewCharacter);if(!purchase.ok){toast(purchase.error);return;}audio.effect('badge');toast('Character unlocked!');}character=previewCharacter;store.set('character',character);closeCharacters();stats();audio.effect('ui');};
function hud(visible){for(let id of ['hud','stage','controls','chase','active-powers','inventory-controls'])$('#'+id).hidden=!visible;}
function showModal(html){$('#modal-content').innerHTML=html;$('#modal').hidden=false;}
function guide(startAfter=false){showModal(`<span class="eyebrow">YOUR FIRST ADVENTURE</span><h2>Ready, little Krishna?</h2><div class="instruction"><strong>↔</strong><p><b>Swipe left / right</b>Change lanes. Follow the golden makhan tokens.</p></div><div class="instruction"><strong>↑</strong><p><b>Swipe up to jump</b>Leap over the wooden carts.</p></div><div class="instruction"><strong>↓</strong><p><b>Swipe down to slide</b>Duck under the flower gates.</p></div><div class="instruction"><strong>◈</strong><p><b>Catch a little mischief</b>Collect 15 makhan tokens to recover the mala from the danav. Pick up a peacock feather to fly for 8 seconds. The red magnet attracts tokens for 8 seconds; the blue shield blocks one hit.</p></div><p>3 hearts per run. Your best distance and makhan save on this device. Keyboard: arrows / WASD · Space: jump · Esc / P: pause · 1–3: bag powers · F: fullscreen. Mouse users can also drag across the playfield.</p><button class="primary" id="guide-done">${startAfter?'LET’S RUN':'GOT IT'} <span>➜</span></button>`);$('#guide-done').onclick=()=>{$('#modal').hidden=true;store.set('tutorial-v4',true);if(startAfter)start()};}
function start(){if(!bankRun())return;runId=globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random();settlement=null;audio.startMusic();audio.effect('power');footTimer=0;$('#modal').hidden=true;$('#active-powers').textContent='';powerStamp='';$('#menu').hidden=true;$('#character-screen').hidden=true;$('#results').hidden=true;hud(true);world.clear();run=new Run({mode,level});run.intro=4;$('#intro-overlay').hidden=false;$('#controls').hidden=true;$('#inventory-controls').hidden=true;$('#intro-caption').textContent='A quiet morning in Vrindavan…';run.nextRow=65;for(let i=0;i<4;i++)run.add('coin',0,-12-i*7,{y:.95});run.add('glide',0,-80);run.nextPower=180;run.objects.push({id:++run.id,lane:-1,type:'cart',z:-40,done:false},{id:++run.id,lane:1,type:'arch',z:-70,done:false});prevStage=0;finished=false;screen='play';$('#stage-name').textContent=STAGES[0];$('#play-hint').textContent=controlHint;toast(mode==='mission'?`Trail ${level} · Reach ${[400,750,1100][level-1]} metres`:'Collect makhan. Chase the danav!');}
function home(){if(!bankRun())return;$('#intro-overlay').hidden=true;audio.stopMusic();screen='menu';world.menuLayout='home';$('#character-screen').hidden=true;$('#menu').hidden=false;$('#modal').hidden=true;$('#results').hidden=true;hud(false);world.clear();run=null;stats();}
function pause(){if(screen!=='play'||!run||run.state!=='running')return;screen='pause';audio.silence();showModal(`<span class="eyebrow">TAKE A BREATHER</span><h2>Vrindavan can wait.</h2><p>Your run is paused right here.</p><button id="resume" class="primary">KEEP RUNNING <span>➜</span></button><button id="restart" class="secondary">Start this run again</button><button id="pause-settings" class="secondary">Music & settings</button><button id="quit" class="text-button">Back to home</button>`);$('#resume').onclick=resume;$('#restart').onclick=start;$('#quit').onclick=home;$('#pause-settings').onclick=openSettings;}
function resume(){$('#modal').hidden=true;screen='play';audio.startMusic();audio.effect('ui');last=performance.now();}
function bankRun(){if(!run||!runId||economy.state.settled.includes(runId))return true;const complete=run.state==='won'||run.state==='over';const award=complete?recordRun(progress,run):{progress,earned:[],reward:0};settlement={award,total:run.feathers+award.reward};const paid=economy.creditRun(runId,settlement.total);if(!paid.ok){toast(paid.error);return false;}progress=settlement.award.progress;store.set('progress',progress);best=Math.max(best,run.distance);store.set('best',best);stats();return true;}
function result(){if(finished)return;finished=true;screen='result';audio.stopMusic();hud(false);$('#intro-overlay').hidden=true;const newBest=run.distance>best;const saved=bankRun();const award=settlement?.award||{earned:[],reward:0};if(run.state==='won'){unlocked=Math.max(unlocked,Math.min(3,level+1));store.set('unlocked',unlocked);}$('#result-eyebrow').textContent=run.state==='won'?'TRAIL COMPLETE':newBest?'A NEW PERSONAL BEST':'WHAT A JOURNEY';$('#result-title').textContent=run.state==='won'?'Beautifully done!':'Adventure complete';$('#result-sub').textContent=saved?`${run.feathers+award.reward} coins added to your wallet. Visit the Garage!`:'Coins not saved. Tap Retry save before leaving.';$('#result-distance').textContent=Math.floor(run.distance);$('#result-score').textContent=Math.floor(run.score+run.feathers*10).toLocaleString();$('#result-feathers').textContent=run.feathers;$('#result-extra').textContent=`${run.catches} mala recoveries · ${run.bestCombo} best makhan streak`+(award.earned.length?' · '+award.earned.map(b=>b.name).join(', ')+` unlocked! +${award.reward} coins`:'');$('#retry-save').hidden=saved;$('#results').hidden=false;audio.effect(run.state==='won'?'win':award.earned.length?'badge':'over');stats();}
$('#retry-save').onclick=()=>{if(bankRun()){$('#retry-save').hidden=true;$('#result-sub').textContent='Coins saved to your wallet.';}};
function input(a){if(screen!=='play'||run.intro>0)return;const before={lane:run.lane,vy:run.vy,slide:run.slide};run.action(a);if(run.lane!==before.lane)audio.effect('lane');if(a==='jump'&&run.vy!==before.vy)audio.effect('jump');if(a==='slide'&&(run.slide!==before.slide||run.vy!==before.vy))audio.effect('slide');}
$('#start').onclick=()=>{if(!store.get('tutorial-v4',false))guide(true);else start()};$('#again').onclick=start;$('#home').onclick=home;$('#pause').onclick=pause;$('#close-modal').onclick=()=>{if(screen==='pause')resume();else $('#modal').hidden=true};$('#guide-open').onclick=()=>guide(false);

function openGarage(){stats();showModal(`<span class="eyebrow">VRINDAVAN GARAGE</span><h2>Adventure supplies</h2><div class="wallet">● <b>${bank.toLocaleString()}</b> coins</div><p>Earn coins on your runs. Purchases use game coins only.</p><div class="shop-grid">${POWERS.map(p=>`<article class="shop-item"><span class="shop-icon">${p.icon}</span><div><h3>${p.name}</h3><p>${p.detail}</p><small>In bag: ${economy.state.inventory[p.id]} / 9</small></div><button class="secondary" data-buy="${p.id}" ${bank<p.price||economy.state.inventory[p.id]>=9?'disabled':''}>Buy · ${p.price} ●</button></article>`).join('')}</div><p>Use your bag buttons during a run. One item is consumed only when activated. Active powers cannot be accidentally used again.</p><button id="shop-characters" class="primary">Unlock characters <span>›</span></button>`);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const r=economy.buyPower(b.dataset.buy);if(r.ok){audio.effect('collect',1);openGarage();}else toast(r.error);});$('#shop-characters').onclick=()=>{$('#modal').hidden=true;$('#characters-open').click();};}
$('#garage-open').onclick=openGarage;$('#result-garage').onclick=()=>{home();if(screen==='menu')openGarage();};
$('#inventory-controls').innerHTML=POWERS.map(p=>`<button data-use="${p.id}" aria-label="Use ${p.name}"><span>${p.icon}</span><small>${p.name.split(' ').at(-1)}</small><b>0</b></button>`).join('');
function usePower(id){if(screen!=='play'||run.intro>0||run.state!=='running'||run[id]>0)return;const used=economy.consume(id);if(!used.ok){toast(used.error);return;}run.activatePower(id);}
document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>usePower(b.dataset.use));
$('#intro-skip').onclick=()=>run?.skipIntro();
function openSettings(){showModal(`<span class="eyebrow">MAKE IT YOURS</span><h2>Sound & display</h2><div class="display-settings"><h3>Screen fit</h3><p>Automatically fits your screen and rotation.</p><button id="fullscreen-setting" class="secondary"></button><p id="fullscreen-help"></p></div><label class="setting">Background music <input id="music-setting" type="checkbox" ${settings.music?'checked':''}></label><label class="setting">Music volume <input id="music-volume" aria-label="Music volume" type="range" min="0" max="1" step=".05" value="${settings.musicVolume}"></label><label class="setting">Sound effects <input id="sound-setting" type="checkbox" ${settings.sound?'checked':''}></label><label class="setting">Effects volume <input id="sfx-volume" aria-label="Effects volume" type="range" min="0" max="1" step=".05" value="${settings.sfxVolume}"></label><label class="setting">Haptic feedback <input id="vibration-setting" type="checkbox" ${settings.vibration?'checked':''}></label><label class="setting">Graphics <select id="quality-setting"><option value="auto" ${settings.quality==='auto'?'selected':''}>Auto · adaptive</option><option value="high" ${settings.quality==='high'?'selected':''}>Rich</option><option value="low" ${settings.quality==='low'?'selected':''}>Battery saver</option></select></label><p>Original flute-style melody, strings and percussion. Your preferences and achievements save on this device.</p><button id="settings-done" class="primary">${screen==='pause'?'RESUME RUN':'ALL SET'} <span>✓</span></button>`);
syncFullscreenSetting();$('#fullscreen-setting').onclick=toggleFullscreen;
const saveAudio=()=>{settings.music=$('#music-setting').checked;settings.sound=$('#sound-setting').checked;settings.musicVolume=+$('#music-volume').value;settings.sfxVolume=+$('#sfx-volume').value;audio.apply();store.set('settings',settings);};for(const id of ['music-setting','sound-setting','music-volume','sfx-volume'])$('#'+id).oninput=saveAudio;
$('#settings-done').onclick=()=>{saveAudio();settings.vibration=$('#vibration-setting').checked;settings.quality=$('#quality-setting').value;store.set('settings',settings);world.quality(settings.quality);if(screen==='pause')resume();else $('#modal').hidden=true;audio.effect('ui');};}
$('#settings-open').onclick=openSettings;
$('#missions-open').onclick=()=>{audio.effect('ui');showModal(`<h2>Missions</h2><p>Choose your trail or keep running endlessly.</p><div class="mission-trails">${[400,750,1100].map((d,i)=>`<button class="secondary" data-trail="${i+1}" ${i+1>unlocked?'disabled':''}>${i+1>unlocked?'🔒':'⚑'} Trail ${i+1} <strong>${d} m</strong></button>`).join('')}<button class="primary" id="endless-select">∞ Endless Run</button></div><h3>Your challenges</h3><div class="badge-list">${BADGES.map(b=>{const done=progress.claimed.includes(b.id),value=Math.min(b.target,progress[b.key]);return `<article class="badge ${done?'earned':''}"><span class="badge-icon">${done?'✦':'◇'}</span><div><b>${b.name}</b><p>${b.detail}</p><progress value="${value}" max="${b.target}"></progress><small>${done?'COMPLETED':Math.floor(value)+' / '+b.target} · +${b.reward} makhan</small></div></article>`;}).join('')}</div>`);document.querySelectorAll('[data-trail]').forEach(b=>b.onclick=()=>{mode='mission';level=+b.dataset.trail;start();});$('#endless-select').onclick=()=>{mode='endless';start();};};
const touchDevice=matchMedia('(pointer:coarse)').matches;
const controlHint=touchDevice?'SWIPE ← → DODGE · ↑ JUMP · ↓ SLIDE':'ARROWS / WASD · SPACE JUMP · P PAUSE · 1–3 POWERS';
let touch=null;
const canvas=$('#scene');
canvas.addEventListener('pointerdown',e=>{if(screen!=='play'||!e.isPrimary||e.button!==0)return;touch={x:e.clientX,y:e.clientY,id:e.pointerId};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{if(!touch||e.pointerId!==touch.id)return;const action=swipeAction(e.clientX-touch.x,e.clientY-touch.y,canvas.clientWidth,canvas.clientHeight);if(action){input(action);touch=null;}});
for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>touch=null);
function syncFullscreenSetting(){
 const button=$('#fullscreen-setting');if(!button)return;
 const {active,available}=fullscreenState(document,$('#game'));
 const standalone=matchMedia('(display-mode: standalone)').matches||matchMedia('(display-mode: fullscreen)').matches||navigator.standalone===true;
 button.disabled=!available&&!active;
 button.textContent=active?'Exit fullscreen':available?'Enter fullscreen':'Screen fit is active';
 button.setAttribute('aria-pressed',String(active));
 $('#fullscreen-help').textContent=active?'Fullscreen is on. Use this button or Escape to exit.':available?'Hide browser controls for an immersive run. Keyboard shortcut: F.':standalone?'Running in app mode. Your app controls the system bars.':'This browser does not offer fullscreen. The game still fits the available screen. On iPhone, add it to your Home Screen for app mode.';
}
async function toggleFullscreen(){try{await changeFullscreen(document,$('#game'));}catch{toast('Fullscreen is controlled by your browser or app.');}syncFullscreenSetting();scheduleResize();}
for(const event of ['fullscreenchange','webkitfullscreenchange'])document.addEventListener(event,()=>{syncFullscreenSetting();scheduleResize();});
window.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest?.('input,select,textarea,[contenteditable="true"]'))return;const action=keyAction(e.key);if(action&&screen==='play'){e.preventDefault();if(!e.repeat){audio.unlock();input(action);}return;}if(e.repeat)return;const k=e.key.toLowerCase();if(k==='f'){e.preventDefault();toggleFullscreen();}if(['1','2','3'].includes(k)&&screen==='play'){e.preventDefault();usePower(POWERS[Number(k)-1].id);}if(k==='escape'||k==='p'){e.preventDefault();if(screen==='play')pause();else if(screen==='pause')resume();else if(k==='escape'&&screen==='characters')closeCharacters();}});
let resizeFrame=0;
function applyDisplay(){
 const root=$('#game'),v=window.visualViewport;
 const width=v?.width||document.documentElement.clientWidth||innerWidth;
 const height=v?.height||innerHeight;
 root.style.width=width+'px';root.style.height=height+'px';
 root.style.left=(v?.offsetLeft||0)+'px';root.style.top=(v?.offsetTop||0)+'px';
 const metrics=displayMetrics(width,height);
 const field=$('#playfield');field.style.width=metrics.width+'px';field.style.height=metrics.height+'px';
 field.style.setProperty('--ui',metrics.scale);field.dataset.layout=metrics.width>=metrics.height?'wide':'tall';
 world?.resize();
}
function scheduleResize(){if(resizeFrame)return;resizeFrame=requestAnimationFrame(()=>{resizeFrame=0;applyDisplay();});}
if(typeof ResizeObserver!=='undefined')new ResizeObserver(scheduleResize).observe(document.documentElement);
window.visualViewport?.addEventListener('resize',scheduleResize);
window.visualViewport?.addEventListener('scroll',scheduleResize);
window.addEventListener('orientationchange',scheduleResize);
// Re-arm the DPR listener when moving a window between monitors.
let dprMedia;
function watchDpr(){dprMedia?.removeEventListener?.('change',onDpr);dprMedia=matchMedia(`(resolution: ${devicePixelRatio||1}dppx)`);dprMedia.addEventListener?.('change',onDpr);}
function onDpr(){watchDpr();scheduleResize();}
watchDpr();applyDisplay();
window.addEventListener('blur',()=>{touch=null;if(screen==='play')pause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(screen==='play')pause();audio.silence();}});window.addEventListener('resize',scheduleResize);$('#scene').addEventListener('webglcontextlost',e=>{e.preventDefault();pause();$('#error-message').textContent='The 3D graphics connection was interrupted. Reload to start a fresh run; your saved best and makhan are safe.';$('#error').hidden=false;});
let prevStage=0,lastHud=0;
function frame(now){const dt=Math.min(.1,(now-last)/1000||0);last=now;if(document.hidden){requestAnimationFrame(frame);return;}try{if(screen==='play'&&run){const priorJump=run.jump;let remaining=dt;while(remaining>0){const step=Math.min(1/60,remaining);run.step(step);remaining-=step;}if(priorJump>0&&run.jump===0)audio.effect('land');footTimer+=dt;if(!run.intro&&!run.jump&&!run.slide&&!run.glide&&footTimer>3.14159/(16+(run.speed-12)*.6)){audio.effect('step');footTimer=0;}for(const event of run.events.splice(0)){if(event==='intro-grab'){$('#intro-caption').textContent='The danav took the mala! Catch him!';audio.effect('hit');}if(event==='intro-end'){$('#intro-overlay').hidden=true;$('#controls').hidden=false;$('#inventory-controls').hidden=false;audio.effect('power');}if(['shield','magnet','shield-block'].includes(event))audio.effect(event);if(event==='shield')toast('Shield ready · blocks one hit');if(event==='magnet')toast('Magnet · 8 seconds');if(event==='shield-block')toast('Shield protected you!');if(event==='collect')audio.effect('collect',run.combo);if(event==='hit'){audio.effect('hit');$('#hit-flash').style.opacity='.8';setTimeout(()=>$('#hit-flash').style.opacity='0',230);if(settings.vibration&&navigator.vibrate)navigator.vibrate(70);toast(run.hearts?'Careful! You have '+run.hearts+' hearts left':'A brave little run!');}if(event==='catch'){toast('Mala recovered! +300 · Keep running!');audio.effect('catch');}if(event==='glide'){toast('Peacock glide · 8 seconds');audio.effect('power');}if(event==='glide-end'){toast('Landing softly…');audio.effect('land');}if(event==='won'||event==='over')result();}
 if(now-lastHud>=66){lastHud=now;document.querySelectorAll('[data-use]').forEach(b=>{const id=b.dataset.use;b.disabled=run.intro>0||run[id]>0||!economy.state.inventory[id];b.querySelector('b').textContent=economy.state.inventory[id];});$('#score').textContent=Math.floor(run.score+run.feathers*10).toLocaleString();$('#distance').textContent=Math.floor(run.distance);$('#feathers').textContent=run.feathers;const stamp=[run.shield,Math.ceil(run.glide*10),Math.ceil(run.magnet*10)].join(':');if(stamp!==powerStamp){powerStamp=stamp;$('#active-powers').innerHTML=(run.shield?'<div class="power-card shield"><b>◈ SHIELD</b><small>1 hit protected</small></div>':'')+[['glide','🪶','GLIDE'],['magnet','🧲','MAGNET']].filter(([key])=>run[key]>0).map(([key,icon,label])=>`<div class="power-card ${run[key]<2?'expiring':''}"><b>${icon} ${label} <em>${Math.ceil(run[key])}s</em></b><div class="power-track"><i style="width:${run[key]/8*100}%"></i></div></div>`).join('');}$('#hearts').textContent='♥ '.repeat(run.hearts)+'♡ '.repeat(3-run.hearts);$('#hearts').setAttribute('aria-label',run.hearts+' hearts');$('#chase-count').textContent=Math.min(15,run.chaseFeathers);$('#stage-name').textContent=STAGES[run.stage];$('#stage-progress').style.width=(mode==='mission'?Math.min(100,run.distance/run.target*100):(run.distance%450)/4.5)+'%';if(run.stage!==prevStage){toast('Welcome to '+STAGES[run.stage]);prevStage=run.stage;}if(run.distance>80)$('#play-hint').textContent=run.combo>=5?'✦ '+run.combo+' MAKHAN STREAK':'COLLECT 15 MAKHAN TO CATCH THE DANAV';}}
 world.update(screen==='pause'||screen==='result'?0:dt,run,screen==='menu'||screen==='characters');requestAnimationFrame(frame);}catch(err){audio.silence();console.error(err);$('#error-message').textContent='The run encountered a technical issue. Reload to try again.';$('#error').hidden=false;}}
try{world=new World($('#scene'),settings.quality);world.character(character);stats();$('#loading').hidden=true;requestAnimationFrame(frame);}catch(err){console.error(err);$('#loading').hidden=true;$('#error').hidden=false;}
